    private String sourceFamily(){return SoundMix.LIBRARY.length>0&&Arrays.asList(SoundMix.LIBRARY).contains(mix.primary)?"Bundled · "+mix.primary:mix.primary;}
    private void sourceOption(LinearLayout body,String icon,String name,String value,String source,Runnable action){LinearLayout row=option(body,icon,name,(mix.primary.equals(source)?"Selected · ":"")+value,action);row.setSelected(mix.primary.equals(source));if(row.isSelected())row.setBackground(Design.touch(this,NightDialTokens.RAISED,12));}
    private void importBanner(LinearLayout body){if(audioImport==null)return;LinearLayout checking=Design.row(this);importStatus=Design.text(this,"Checking audio…",12,500,MUTED);checking.addView(importStatus,new LinearLayout.LayoutParams(0,-2,1));TextView cancel=Design.text(this,"Cancel",13,600,INK);cancel.setGravity(Gravity.CENTER);cancel.setMinimumHeight(dp(48));cancel.setPadding(dp(16),0,dp(16),0);cancel.setFocusable(true);cancel.setContentDescription("Cancel audio import");cancel.setBackground(Design.touch(this,PANEL,12));cancel.setOnClickListener(v->{InteractionFeedback.action(v);cancelImport();});checking.addView(cancel);body.addView(checking);Design.space(body,14);}
    private void rememberScroll(){if(scroll!=null)scrolls.put(page,scroll.getScrollY());}
    private void finishPage(){int token=viewGeneration;ScrollView current=scroll;if(current!=null)current.post(()->{if(!isDestroyed()&&token==viewGeneration)current.scrollTo(0,scrolls.getOrDefault(page,0));});}
    private void navigate(String destination){rememberScroll();page=destination;render();}
    private void external(Class<?> target){rememberScroll();startActivity(RecordUi.intent(this,target));}
    private void removeAudio(){if(audioImport!=null)return;SleepSoundService.pauseForSelection();mix.uri="";mix.title="My audio";if(mix.primary.equals("My audio"))mix.primary="Rain";save();render();}
    private String description(){return switch(mix.primary){case "Rain"->"A steady rain to help you relax";case "Ocean"->"Slow waves, a quiet shore";case "Fireplace"->"A soft fire for a quiet evening";case "Wind"->"A gentle breeze through the trees";case "Brown noise"->"A low, continuous noise";case "Ambient rotation"->"Bundled loops rotate every "+mix.rotation.minutes+" min playing · one overall timer";case "Local playlist"->"Local documents play once in order · manual Play only";case "Internet radio"->"Public HTTPS stream · network/data required · manual Play only";case "Binaural tones"->"Stereo · left "+mix.binauralCarrier+" Hz / right "+(mix.binauralCarrier+mix.binauralBeat)+" Hz · headphones needed";default->"Keep the original file available for playback";};}
    private void showArt(){if(hero!=null){hero.setImageBitmap(artwork.get(SoundMix.SOURCES.contains(mix.primary)&&!mix.primary.equals("My audio")&&!mix.primary.equals("Brown noise")&&!mix.primary.equals(BinauralTones.NAME)&&!mix.primary.equals(SoundPlaylist.NAME)&&!mix.primary.equals(AmbientRotation.NAME)&&!mix.primary.equals(SleepRadio.NAME)?mix.primary:"My audio"));}for(Map.Entry<String,ImageView> tile:tiles.entrySet())tile.getValue().setImageBitmap(artwork.get(tile.getKey()));}
    private void gain(LinearLayout body,String icon,String name,int value,boolean brown){LinearLayout row=Design.row(this);Design.Icon glyph=new Design.Icon(this,icon,MUTED);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(dp(27),dp(27));ip.rightMargin=dp(18);row.addView(glyph,ip);LinearLayout slider=Design.col(this),labels=Design.row(this);TextView sourceName=Design.text(this,name,15,500,MUTED);sourceName.setMaxLines(1);sourceName.setEllipsize(android.text.TextUtils.TruncateAt.END);labels.addView(sourceName,new LinearLayout.LayoutParams(0,-2,1));TextView percent=Design.text(this,value+"%",16,600,MUTED);labels.addView(percent);slider.addView(labels);SeekBar seek=new SeekBar(this);seek.setMax(100);seek.setProgress(value);seek.setContentDescription(name+" volume");seek.setProgressTintList(ColorStateList.valueOf(Design.VIOLET));seek.setProgressBackgroundTintList(ColorStateList.valueOf(PANEL));seek.setThumbTintList(ColorStateList.valueOf(INK));seek.setPadding(dp(2),0,dp(2),0);SoundSliders.style(seek);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){private boolean dragging;private int began;public void onStartTrackingTouch(SeekBar b){dragging=true;began=b.getProgress();}public void onStopTrackingTouch(SeekBar b){dragging=false;if(b.getProgress()!=began)InteractionFeedback.selection(b);save();}public void onProgressChanged(SeekBar b,int n,boolean user){if(user){if(!dragging)InteractionFeedback.selection(b);if(brown)mix.brownGain=n;else mix.primaryGain=n;percent.setText(getString(R.string.sound_gain_percent,n));SoundPreferences.save(SleepSoundsActivity.this,mix);SleepSoundService.update(SleepSoundsActivity.this);}}});slider.addView(seek,new LinearLayout.LayoutParams(-1,dp(48)));row.addView(slider,new LinearLayout.LayoutParams(0,-2,1));body.addView(row);}
